<?php
$active_menu='timesheets';include 'header.php';require_once __DIR__.'/../foundation.php';oecrm_require_permission($conn,'timesheets','view');$companyId=oecrm_current_company_id($conn);
$month=preg_match('/^\d{4}-\d{2}$/',$_GET['month']??'')?$_GET['month']:date('Y-m');$status=trim($_GET['status']??'');$employee=(int)($_GET['employee_id']??0);$start=$month.'-01';$end=date('Y-m-t',strtotime($start));$where='t.company_id=? AND t.work_date BETWEEN ? AND ?';$types='iss';$params=[$companyId,$start,$end];if(in_array($status,['draft','submitted','approved','rejected'],true)){$where.=' AND t.status=?';$types.='s';$params[]=$status;}if($employee){$where.=' AND t.employee_id=?';$types.='i';$params[]=$employee;}
$sql='SELECT t.*,e.name employee_name,e.employeeCode,p.projectName,c.display_name client_name,tk.taskTitle FROM timesheet_entries t JOIN employeestbl e ON e.id=t.employee_id JOIN projectstbl p ON p.id=t.project_id LEFT JOIN tasktbl tk ON tk.id=t.task_id LEFT JOIN clients c ON c.id=p.client_id WHERE '.$where.' ORDER BY t.work_date DESC,e.name';$s=mysqli_prepare($conn,$sql);mysqli_stmt_bind_param($s,$types,...$params);mysqli_stmt_execute($s);$rows=mysqli_stmt_get_result($s);
$safeStart=mysqli_real_escape_string($conn,$start);$safeEnd=mysqli_real_escape_string($conn,$end);$stats=mysqli_fetch_assoc(mysqli_query($conn,'SELECT COALESCE(SUM(hours),0) total_hours,COALESCE(SUM(billable_hours),0) billable,SUM(status="submitted") pending,COUNT(DISTINCT employee_id) employees FROM timesheet_entries WHERE company_id='.(int)$companyId." AND work_date BETWEEN '$safeStart' AND '$safeEnd'"));$employees=mysqli_query($conn,'SELECT DISTINCT e.id,e.employeeCode,e.name FROM employeestbl e JOIN timesheet_entries t ON t.employee_id=e.id WHERE t.company_id='.(int)$companyId.' ORDER BY e.name');$flash=$_SESSION['timesheet_flash']??'';unset($_SESSION['timesheet_flash']);
?><div id="page-wrapper" class="compact-admin-page timesheet-page"><?php if($flash):?><div class="alert alert-success"><?php echo oecrm_h($flash);?></div><?php endif;?><div class="resource-summary"><div><i class="fa fa-clock-o"></i><span><small>Total Hours</small><strong><?php echo number_format($stats['total_hours'],2);?></strong></span></div><div><i class="fa fa-money"></i><span><small>Billable Hours</small><strong><?php echo number_format($stats['billable'],2);?></strong></span></div><div><i class="fa fa-hourglass-half"></i><span><small>Pending Review</small><strong><?php echo (int)$stats['pending'];?></strong></span></div><div><i class="fa fa-users"></i><span><small>Contributors</small><strong><?php echo (int)$stats['employees'];?></strong></span></div></div>
<div class="panel panel-default"><div class="panel-heading foundation-heading"><span>Timesheet Review</span></div><div class="panel-body"><form class="timesheet-filters" method="get"><input class="form-control" type="month" name="month" value="<?php echo oecrm_h($month);?>"><select class="form-control" name="employee_id"><option value="">All employees</option><?php while($e=mysqli_fetch_assoc($employees)):?><option value="<?php echo $e['id'];?>" <?php echo $employee==$e['id']?'selected':'';?>><?php echo oecrm_h($e['employeeCode'].' - '.$e['name']);?></option><?php endwhile;?></select><select class="form-control" name="status"><option value="">All statuses</option><?php foreach(['draft','submitted','approved','rejected'] as $v):?><option value="<?php echo $v;?>" <?php echo $status===$v?'selected':'';?>><?php echo ucfirst($v);?></option><?php endforeach;?></select><button class="btn btn-default"><i class="fa fa-filter"></i> Filter</button></form>
<div class="table-responsive"><table class="table foundation-table"><thead><tr><th>Date</th><th>Employee</th><th>Client / Project</th><th>Work Log</th><th>Hours</th><th>Billable</th><th>Status</th><th>Review</th></tr></thead><tbody><?php if(mysqli_num_rows($rows)===0):?><tr><td colspan="8" class="empty-cell">No timesheet entries found.</td></tr><?php endif;?><?php while($r=mysqli_fetch_assoc($rows)):?><tr><td><?php echo date('d M Y',strtotime($r['work_date']));?></td><td><strong><?php echo oecrm_h($r['employee_name']);?></strong><small><?php echo oecrm_h($r['employeeCode']);?></small></td><td><?php echo oecrm_h($r['projectName']);?><small><?php echo oecrm_h(($r['taskTitle']?$r['taskTitle'].' | ':'').$r['client_name']);?></small></td><td class="timesheet-description"><?php echo oecrm_h($r['description']);?><?php if($r['rejection_reason']):?><small class="text-danger"><?php echo oecrm_h($r['rejection_reason']);?></small><?php endif;?></td><td><?php echo number_format($r['hours'],2);?></td><td><?php echo number_format($r['billable_hours'],2);?></td><td><span class="client-status <?php echo $r['status'];?>"><?php echo ucfirst($r['status']);?></span></td><td><?php if($r['status']==='submitted'&&oecrm_can($conn,'timesheets','review')):?><form method="post" action="timesheetAction.php" class="review-actions"><?php echo oecrm_csrf_field();?><input type="hidden" name="id" value="<?php echo $r['id'];?>"><input class="form-control input-sm" name="reason" placeholder="Reason if rejecting"><button name="decision" value="approved" class="btn btn-success btn-xs" title="Approve"><i class="fa fa-check"></i></button><button name="decision" value="rejected" class="btn btn-danger btn-xs" title="Reject"><i class="fa fa-times"></i></button></form><?php else:?>-<?php endif;?></td></tr><?php endwhile;?></tbody></table></div></div></div></div><?php include 'footer.php';?>
